1	package stowage
2	
3	import (
4		"math"
5		"sort"
6		"strconv"
7		"strings"
8	)
9	
10	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
11	//
12	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
13	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
14	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
15	// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
16	// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
17	// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
18	// 参与比较。
19	//
20	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
21	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
22	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
23	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
24	// 范围也会被拒绝。
25	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
26		r.mu.Lock()
27		defer r.mu.Unlock()
28	
29		aid := strings.TrimSpace(adjustmentID)
30		if aid == "" {
31			return nil, fail(ErrInvalidID, "", "调整编号为空")
32		}
33	
34		// f 构造带调整编号的错误。
35		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
36			e := fail(kind, id, format, args...)
37			e.AdjustmentID = aid
38			return e
39		}
40	
41		// 幂等：编号已成功使用过。
42		if saved, ok := r.adjustments[aid]; ok {
43			if r.contents[aid] == canonicalKey(ops) {
44				return cloneResult(saved), nil
45			}
46			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
47		}
48	
49		if len(ops) == 0 {
50			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
51		}
52	
53		vops, final, affected, err := r.prepareOps(ops, f)
54		if err != nil {
55			return nil, err
56		}
57	
58		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整。
59		if rej := r.firstRejection(final); rej != nil {
60			switch rej.Kind {
61			case ErrOverflow:
62				return nil, f(ErrOverflow, rej.CompartmentID, "舱位 %s 重量合计超过 int64 可表示范围", rej.CompartmentID)
63			case ErrOverweight:
64				return nil, f(ErrOverweight, rej.CompartmentID,
65					"舱位 %s 总重量 %d 千克超过最大承重 %d 千克",
66					rej.CompartmentID, rej.UsedWeight, r.compartments[rej.CompartmentID].maxWeight)
67			default:
68				return nil, f(ErrMixedLoading, rej.firstOffender(),
69					"舱位 %s 存在不同目的地货物，但货物 %s 不允许混装",
70					rej.CompartmentID, rej.firstOffender())
71			}
72		}
73	
74		// 全部合法，正式生效。先计算受影响舱位调整前后的重量。
75		cargoChanges := make([]CargoChange, 0, len(vops))
76		compChanges := make([]CompartmentChange, 0, len(affected))
77		for id := range affected {
78			compChanges = append(compChanges, CompartmentChange{
79				CompartmentID: id,
80				WeightBefore:  sumSet(r.compartments[id].cargo),
81				WeightAfter:   sumSet(final[id]),
82			})
83		}
84		sort.Slice(compChanges, func(i, j int) bool {
85			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
86		})
87	
88		for _, v := range vops {
89			c := v.cargo
90			from := c.compartmentID
91			var to string
92			switch v.op.Kind {
93			case OpLoad:
94				r.compartments[v.target.id].cargo[c.id] = c
95				c.compartmentID = v.target.id
96				to = v.target.id
97			case OpUnload:
98				delete(r.compartments[from].cargo, c.id)
99				c.compartmentID = ""
100			case OpMove:
101				delete(r.compartments[from].cargo, c.id)
102				r.compartments[v.target.id].cargo[c.id] = c
103				c.compartmentID = v.target.id
104				to = v.target.id
105			}
106			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: from, To: to})
107		}
108		sort.Slice(cargoChanges, func(i, j int) bool {
109			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
110		})
111	
112		result := &AdjustmentResult{
113			ID:                 aid,
114			CargoChanges:       cargoChanges,
115			CompartmentChanges: compChanges,
116		}
117		r.adjustments[aid] = result
118		r.contents[aid] = canonicalKey(ops)
119		return cloneResult(result), nil
120	}
121	
122	// validOp 是一条通过逐条校验的操作，附带其涉及的内部记录。
123	type validOp struct {
124		op     Op
125		cargo  *cargo
126		target *compartment // 装载/移动的目标舱位；卸下时为 nil
127	}
128	
129	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
130	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
131	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
132	// 目标舱位（交换中的两个舱位都会纳入）。
133	func (r *Registry) prepareOps(
134		ops []Op,
135		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
136	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
137		seen := make(map[string]bool)
138		vops = make([]validOp, 0, len(ops))
139		affected = make(map[string]bool)
140	
141		for _, op := range ops {
142			cid := strings.TrimSpace(op.CargoID)
143			if cid == "" {
144				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
145			}
146			c, ok := r.cargos[cid]
147			if !ok {
148				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
149			}
150			if seen[cid] {
151				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
152			}
153			seen[cid] = true
154	
155			switch op.Kind {
156			case OpLoad:
157				if c.compartmentID != "" {
158					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
159				}
160				tid := strings.TrimSpace(op.Target)
161				if tid == "" {
162					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
163				}
164				t, ok := r.compartments[tid]
165				if !ok {
166					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
167				}
168				vops = append(vops, validOp{op, c, t})
169				affected[t.id] = true
170			case OpUnload:
171				if c.compartmentID == "" {
172					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
173				}
174				vops = append(vops, validOp{op, c, nil})
175				affected[c.compartmentID] = true
176			case OpMove:
177				if c.compartmentID == "" {
178					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
179				}
180				tid := strings.TrimSpace(op.Target)
181				if tid == "" {
182					return nil, nil, nil, failf(ErrInvalidID, "", "目标舱位编号为空")
183				}
184				t, ok := r.compartments[tid]
185				if !ok {
186					return nil, nil, nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
187				}
188				if t.id == c.compartmentID {
189					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
190				}
191				vops = append(vops, validOp{op, c, t})
192				affected[c.compartmentID] = true
193				affected[t.id] = true
194			default:
195				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(op.Kind))
196			}
197		}
198	
199		// 在模拟配载上应用全部操作，判断以完成后的最终状态为准。
200		final = make(map[string]map[string]*cargo, len(r.compartments))
201		for id, comp := range r.compartments {
202			set := make(map[string]*cargo, len(comp.cargo))
203			for cid, c := range comp.cargo {
204				set[cid] = c
205			}
206			final[id] = set
207		}
208		for _, v := range vops {
209			switch v.op.Kind {
210			case OpLoad:
211				final[v.target.id][v.cargo.id] = v.cargo
212			case OpUnload:
213				delete(final[v.cargo.compartmentID], v.cargo.id)
214			case OpMove:
215				delete(final[v.cargo.compartmentID], v.cargo.id)
216				final[v.target.id][v.cargo.id] = v.cargo
217			}
218		}
219		return vops, final, affected, nil
220	}
221	
222	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
223	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
224	// 调用方必须持有 r.mu。
225	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
226		var rejs []*Rejection
227		for id, set := range final {
228			comp := r.compartments[id]
229	
230			// 重量原因：溢出优先，溢出时不提供任何重量数值。
231			var sum int64
232			overflow := false
233			for _, c := range set {
234				if c.weight > math.MaxInt64-sum {
235					overflow = true
236					break
237				}
238				sum += c.weight
239			}
240			var rej *Rejection
241			if overflow {
242				rej = &Rejection{
243					CompartmentID: id,
244					Kind:          ErrOverflow,
245					MaxWeight:     comp.maxWeight,
246				}
247			} else if sum > comp.maxWeight {
248				rej = &Rejection{
249					CompartmentID:   id,
250					Kind:            ErrOverweight,
251					MaxWeight:       comp.maxWeight,
252					UsedWeight:      sum,
253					RemainingWeight: comp.maxWeight - sum,
254					Overweight:      sum - comp.maxWeight,
255				}
256			}
257	
258			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
259			destinations := make(map[string][]string)
260			destSet := make(map[string]bool)
261			var offenders []string
262			for _, c := range set {
263				destinations[c.destination] = append(destinations[c.destination], c.id)
264				destSet[c.destination] = true
265				if !c.allowMixed {
266					offenders = append(offenders, c.id)
267				}
268			}
269			if len(destSet) > 1 && len(offenders) > 0 {
270				dests := make([]MixedDestination, 0, len(destinations))
271				for dest, ids := range destinations {
272					sorted := append([]string(nil), ids...)
273					sort.Strings(sorted)
274					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
275				}
276				sort.Slice(dests, func(i, j int) bool {
277					return dests[i].Destination < dests[j].Destination
278				})
279				sort.Strings(offenders)
280				mr := &Rejection{
281					CompartmentID:  id,
282					Kind:           ErrMixedLoading,
283					MaxWeight:      comp.maxWeight,
284					Destinations:   dests,
285					OffendingCargo: offenders,
286				}
287				if rej != nil {
288					rejs = append(rejs, rej, mr)
289				} else {
290					rejs = append(rejs, mr)
291				}
292			} else if rej != nil {
293				rejs = append(rejs, rej)
294			}
295		}
296		return rejs
297	}
298	
299	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
300	// 调用方必须持有 r.mu。
301	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
302		rejs := r.evaluateFinal(final)
303		if len(rejs) == 0 {
304			return nil
305		}
306		sort.Slice(rejs, func(i, j int) bool {
307			if rejs[i].CompartmentID != rejs[j].CompartmentID {
308				return rejs[i].CompartmentID < rejs[j].CompartmentID
309			}
310			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
311		})
312		return rejs[0]
313	}
314	
315	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
316	func rejKindOrder(k ErrorKind) int {
317		switch k {
318		case ErrOverflow, ErrOverweight:
319			return 0
320		default:
321			return 1
322		}
323	}
324	
325	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
326	func (x *Rejection) firstOffender() string {
327		if len(x.OffendingCargo) == 0 {
328			return ""
329		}
330		return x.OffendingCargo[0]
331	}
332	
333	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
334	// 即视为相同内容，排列顺序不影响判断。卸下操作忽略目标舱位（执行时
335	// 同样忽略），其目标值不影响内容判断；装载与移动的目标舱位参与比较。
336	// 编号按去掉首尾空白后的原始字节精确比较：任何字节差异都视为不同内容，
337	// 包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD 的编号也不相同。
338	func canonicalKey(ops []Op) string {
339		sorted := make([]Op, len(ops))
340		for i, op := range ops {
341			target := strings.TrimSpace(op.Target)
342			if op.Kind == OpUnload {
343				target = ""
344			}
345			sorted[i] = Op{
346				Kind:    op.Kind,
347				CargoID: strings.TrimSpace(op.CargoID),
348				Target:  target,
349			}
350		}
351		sort.Slice(sorted, func(i, j int) bool {
352			if sorted[i].Kind != sorted[j].Kind {
353				return sorted[i].Kind < sorted[j].Kind
354			}
355			if sorted[i].CargoID != sorted[j].CargoID {
356				return sorted[i].CargoID < sorted[j].CargoID
357			}
358			return sorted[i].Target < sorted[j].Target
359		})
360		// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
361		// 任意字节内容都不会因分隔符或转义而碰撞。
362		var b strings.Builder
363		for _, op := range sorted {
364			b.WriteString(strconv.Itoa(int(op.Kind)))
365			b.WriteByte('|')
366			writeRawField(&b, op.CargoID)
367			writeRawField(&b, op.Target)
368		}
369		return b.String()
370	}
371	
372	// writeRawField 以“长度:原始字节”的形式写入一个字段。
373	func writeRawField(b *strings.Builder, s string) {
374		b.WriteString(strconv.Itoa(len(s)))
375		b.WriteByte(':')
376		b.WriteString(s)
377	}
378

