1	package stowage
2	
3	import (
4		"errors"
5		"math"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// 本文件为正式提交（Adjust）补充回归保障：一批安排在多个舱位同时触发
12	// 重量与混装限制时，正式提交只返回一个结构化错误，报告顺序固定为
13	// 先按舱位编号字典序选最靠前的违规舱位、同一舱位先重量后混装；被拒绝
14	// 后原配载可完整回查（整批原子性）；并保护 Preview（列全拒绝原因）与
15	// Adjust（只报一个）两种入口各自的用途。
16	
17	// ---------- 测试辅助 ----------
18	
19	func mustRegisterCompartment(t *testing.T, r *Registry, id string, maxWeight int64) {
20		t.Helper()
21		if err := r.RegisterCompartment(id, maxWeight); err != nil {
22			t.Fatalf("登记舱位 %s 失败: %v", id, err)
23		}
24	}
25	
26	func mustRegisterCargo(t *testing.T, r *Registry, id string, weight int64, dest string, mixed bool) {
27		t.Helper()
28		if err := r.RegisterCargo(id, weight, dest, mixed); err != nil {
29			t.Fatalf("登记货物 %s 失败: %v", id, err)
30		}
31	}
32	
33	// submitExpectReject 提交并断言调整被拒绝：err 为单条 *Error，且不返回
34	// 成功结果。返回该结构化错误供调用方核对 Kind、ID、AdjustmentID 与说明。
35	func submitExpectReject(t *testing.T, r *Registry, id string, ops []Op) *Error {
36		t.Helper()
37		res, err := r.Adjust(id, ops)
38		if err == nil {
39			t.Fatalf("调整 %s 应被拒绝，却返回成功: %+v", id, res)
40		}
41		if res != nil {
42			t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
43		}
44		var se *Error
45		if !errors.As(err, &se) {
46			t.Fatalf("期望 *Error，实际为 %T: %v", err, err)
47		}
48		return se
49	}
