65	func snapshotCargo(r *Registry, ids ...string) map[string]CargoView {
66		snap := make(map[string]CargoView, len(ids))
67		for _, id := range ids {
68			v, err := r.Cargo(id)
69			if err != nil {
70				panic(err)
71			}
72			snap[id] = *v
73		}
74		return snap
75	}
